SELECT e.id AS id, e.express_no AS expressNo, e.company_id AS companyId, c.company_name AS companyName, e.sender_name AS senderName, e.sender_phone AS senderPhone, e.receiver_name AS receiverName, e.receiver_phone AS receiverPhone, e.receiver_user_id AS receiverUserId, e.pickup_code AS pickupCode, e.location_id AS locationId, s.shelf_no AS shelfNo, l.location_no AS locationNo, e.status AS status, e.size_type AS sizeType, e.weight AS weight, DATE_FORMAT(e.arrival_time, '%Y-%m-%d %H:%i:%s') AS arrivalTime, DATE_FORMAT(e.storage_time, '%Y-%m-%d %H:%i:%s') AS storageTime, DATE_FORMAT(e.pickup_time, '%Y-%m-%d %H:%i:%s') AS pickupTime, e.overdue_flag AS overdueFlag, e.remark AS remark, DATE_FORMAT(e.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(e.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime FROM express e LEFT JOIN express_company c ON c.id = e.company_id LEFT JOIN shelf_location l ON l.id = e.location_id LEFT JOIN shelf s ON s.id = l.shelf_id WHERE e.deleted = 0 AND (e.receiver_user_id = #{userId}
OR e.receiver_phone = #{phone} )
AND ( e.express_no LIKE CONCAT('%', #{keyword}, '%') OR e.receiver_phone LIKE CONCAT('%', #{keyword}, '%') )
AND e.status = #{status}
ORDER BY e.id DESC

