UPDATE express
SET location_id = #{locationId},
    status = #{status},
    storage_time = #{storageTime},
    update_time = #{updateTime}
WHERE id = #{id}
  AND status = #{expectStatus}
  AND location_id IS NULL
  AND deleted = 0

UPDATE express
SET status = #{status},
    pickup_time = #{pickupTime},
    location_id = NULL,
    update_time = #{updateTime}
WHERE id = #{id}
  AND status = #{expectStatus}
  AND deleted = 0

UPDATE express
SET overdue_flag = 1,
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 0

UPDATE express
SET location_id = #{locationId},
    update_time = #{updateTime}
WHERE id = #{id}
  AND location_id = #{oldLocationId}
  AND status = #{expectStatus}
  AND deleted = 0
